from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def is_balanced(s: str) -> bool:
        """Check if the string is balanced."""
        count = 0
        for char in s:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    def find_group_start(s: str) -> int:
        """Find the start index of the first group in the string."""
        count = 0
        for i, char in enumerate(s):
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count == 0:
                return i
        return -1

    def find_group_end(s: str, start: int) -> int:
        """Find the end index of the group starting at the given index."""
        count = 0
        for i, char in enumerate(s[start:], start):
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count == 0:
                return i
        return -1

    result = []
    while paren_string:
        start = find_group_start(paren_string)
        if start == -1:
            break
        end = find_group_end(paren_string, start)
        if end == -1:
            break
        result.append(paren_string[:end+1])
        paren_string = paren_string[end+1:]
    return result
